import{_ as r,o as t,c as o,a2 as l}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"兔族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/兔族.md","filePath":"表层/种族/兔族.md","lastUpdated":null}'),e={name:"表层/种族/兔族.md"};function i(n,a,s,h,u,d){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="兔族" tabindex="-1">兔族 <a class="header-anchor" href="#兔族" aria-label="Permalink to &quot;兔族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>兔族是黑暗时代出现的新兴种族，居于南方深山密林之中，凭借极强的机动与潜伏能力远离黑暗时代的混乱，过着与大自然和谐共生的游猎生活。黑暗时代中，兔族建立了收留各处流亡奴隶的村落，为后续其余种族的独立埋下了种子。当前兔族族群仍在发展，与牛族、鹤族联系紧密，日益发展的客观事实让他们越来越难以继续逃避参与大陆局势的责任。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，具有兔类动物的典型福瑞形态。</li><li><strong>耳朵</strong>：高高竖起的双耳，极为显眼，是兔族最重要的种族特征，带来极为敏锐的侦查能力。</li><li><strong>体格</strong>：体型偏小，力量不算大，但动作极为敏捷。</li><li><strong>下肢</strong>：善跳跃，奔跑速度快。</li><li><strong>毛色</strong>：以白色、灰色、棕色为主，常见多种毛色变种。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-机动性与敏锐侦查" tabindex="-1">核心特质：机动性与敏锐侦查 <a class="header-anchor" href="#核心特质-机动性与敏锐侦查" aria-label="Permalink to &quot;核心特质：机动性与敏锐侦查&quot;">​</a></h3><ul><li><strong>机动性极强</strong>：力量不算大但速度极快，善跑善跳，在复杂地形中机动性极高。</li><li><strong>敏锐侦查</strong>：高高竖起的双耳带来极为敏锐的侦查能力，善于在远处察觉危险并提前做出反应。</li><li><strong>潜伏能力</strong>：善于隐藏和潜伏，在深林与大自然中几乎无法被发现。</li><li><strong>隐蔽生存</strong>：不追求强权或军事实力，以隐秘和避免冲突为首要生存策略。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="黑暗时代-避难所建立者" tabindex="-1">黑暗时代：避难所建立者 <a class="header-anchor" href="#黑暗时代-避难所建立者" aria-label="Permalink to &quot;黑暗时代：避难所建立者&quot;">​</a></h3><p>黑暗时代中，兔族居于南方深山密林，过着与大自然和谐共生的游猎生活，凭借极强的机动与潜伏能力远离黑暗时代的混乱。</p><p>约黑暗时代 120 年时，兔族在南方山林中建立<strong>收留各处流亡奴隶的村落</strong>。黑暗时代的狼村、狐村等村落便初步建立于此——这些村落为后续其余种族的独立埋下了种子。</p><h3 id="保持独立的三个因素" tabindex="-1">保持独立的三个因素 <a class="header-anchor" href="#保持独立的三个因素" aria-label="Permalink to &quot;保持独立的三个因素&quot;">​</a></h3><p>兔族在黑暗时代能够保持相对独立、不被新五族直接管辖，源于三个因素：</p><ul><li><strong>地形壁垒</strong>：兔族栖息在南方深山密林之中，道路难行、瘴气弥漫、极易迷路，大规模武装进入的成本与收益完全不成比例。</li><li><strong>种族特质</strong>：兔族的机动性和侦查能力极强。他们无法打败法师，但可以让法师永远抓不到他们——捕奴队进山，兔族可以在一刻钟内全员撤离，只留下空窝棚。</li><li><strong>政治经济学上的&quot;不值&quot;</strong>：兔族没有先进的农业技术，没有工业基础，没有值得掠夺的知识积累，甚至作为奴隶的性价比也不如牛族和狼族。对统治阶层来说，兔族是&quot;不值得征服的&quot;。</li></ul><blockquote><p>这种独立不是荣耀，而是一种残忍的轻视——他们甚至不配被奴役。</p></blockquote><h3 id="兔村的起源与长老科伦" tabindex="-1">兔村的起源与长老科伦 <a class="header-anchor" href="#兔村的起源与长老科伦" aria-label="Permalink to &quot;兔村的起源与长老科伦&quot;">​</a></h3><p>兔村最初只是一片山林深处的窝棚群，住着几十个逃亡者。兔村能够建立并度过第一个冬天，与长老<strong>科伦</strong>的态度密切相关。</p><p>科伦是一位精于计算生存概率的守成者，但他的计算中始终保留着一条底线：<strong>在不危害族群的前提下，不主动作恶</strong>。他对逃亡者的态度是&quot;默许但不参与&quot;——不赶人，不举报，但也不公开帮忙。他会在长老会上说&quot;那些人跟我们没关系&quot;，但私下里知道有年轻兔族在偷偷给逃亡者送食物时，会假装没看到。</p><p>他的&quot;不告发&quot;是兔村能够度过第一个冬天的关键——他没有做任何英雄式的举动，只是在某次法师的例行询问中，选择少说了一句话，而这则成为了兔村的起源。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>当前兔族<strong>族群仍在发展</strong>，保持着深林中的隐蔽生存方式：</p><ul><li><strong>隐居生活</strong>：居于深林之中，过着与大自然和谐共生的游猎生活。</li><li><strong>与隐居种族的联系</strong>：与牛族、鹤族同为隐居种族，联系紧密，形成了相对独立的隐居社区。</li><li><strong>日益无法回避的局势</strong>：虽只愿遗世独立，但日益发展的客观事实让他们越来越难以继续逃避参与大陆局势的责任。</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li><li><a href="./牛族">牛族</a></li><li><a href="./鹤族">鹤族</a></li><li><a href="./狼族">狼族</a></li><li><a href="./狐族">狐族</a></li></ul><hr>',31)])])}const q=r(e,[["render",i]]);export{c as __pageData,q as default};
